#include "RNSScreenRemovalListener.h"
#include <react/renderer/mounting/ShadowViewMutation.h>
using namespace facebook::react;

std::optional<MountingTransaction> RNSScreenRemovalListener::pullTransaction(
    SurfaceId surfaceId,
    MountingTransaction::Number transactionNumber,
    const TransactionTelemetry &telemetry,
    ShadowViewMutationList mutations) const {
  // Build/update a persistent tag→componentName map from this transaction.
  // RN 0.79 removed 'parentShadowView' from ShadowViewMutation; we rebuild
  // parent identity by tracking every view we see via newChildShadowView.
  for (const ShadowViewMutation &mutation : mutations) {
    if (mutation.newChildShadowView.tag != 0 &&
        mutation.newChildShadowView.componentName != nullptr) {
      tagToComponentName_[mutation.newChildShadowView.tag] =
          mutation.newChildShadowView.componentName;
    }
    if (mutation.type == ShadowViewMutation::Type::Delete &&
        mutation.oldChildShadowView.tag != 0) {
      tagToComponentName_.erase(mutation.oldChildShadowView.tag);
    }
  }

  for (const ShadowViewMutation &mutation : mutations) {
    if (mutation.type == ShadowViewMutation::Type::Remove &&
        mutation.oldChildShadowView.componentName != nullptr) {
      auto it = tagToComponentName_.find(mutation.parentTag);
      if (it != tagToComponentName_.end() &&
          it->second == "RNSScreenStack") {
        listenerFunction_(mutation.oldChildShadowView.tag);
      }
    }
  }

  return MountingTransaction{
      surfaceId, transactionNumber, std::move(mutations), telemetry};
}

bool RNSScreenRemovalListener::shouldOverridePullTransaction() const {
  return true;
}
